// test/flutter_test_config.dart — runs once for every test in this tree
import 'dart:async';
import 'dart:io';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';

Future<void> testExecutable(FutureOr<void> Function() testMain) async {
  TestWidgetsFlutterBinding.ensureInitialized();
  await _loadFont('Inter', ['assets/fonts/Inter-Regular.ttf',
                            'assets/fonts/Inter-Bold.ttf']);
  // One surface for every golden — no per-test drift. `binding.window` is
  // deprecated; the test view is reached through the platform dispatcher.
  final view = TestWidgetsFlutterBinding.instance.platformDispatcher.views.first;
  view.physicalSize = const Size(1080, 1920);
  view.devicePixelRatio = 3.0;
  await testMain();
}

Future<void> _loadFont(String family, List<String> paths) async {
  final loader = FontLoader(family);
  for (final p in paths) {
    loader.addFont(File(p).readAsBytes().then(ByteData.sublistView));
  }
  await loader.load();
}

